// Signs the request to Convex: `${timestamp}.GET.${path}.` (empty body).
const crypto = require('crypto');
const base = String($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!base || !$env.LENDLOOP_SHARED_SECRET) throw new Error('CONVEX_SITE_URL / LENDLOOP_SHARED_SECRET not set');
const path = '/n8n/overdue-loans';
const ts = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', $env.LENDLOOP_SHARED_SECRET).update(`${ts}.GET.${path}.`).digest('hex');
return [{ json: { url: base + path, ts, signature } }];

// One item per overdue loan. Zero loans -> zero items -> the run ends quietly.
const { date, loans } = $input.first().json;
return (loans || []).map((loan) => ({ json: { ...loan, date } }));

// Sends the reminder (mock, logged) and prepares the SIGNED write-back.
// A failure to send is reported to Convex as status=failed, never swallowed.
const crypto = require('crypto');
const base = String($env.CONVEX_SITE_URL).replace(/\/$/, '');
const path = '/n8n/reminder-result';
const out = [];

for (const item of $input.all()) {
  const loan = item.json;
  let status = 'sent';
  let detail = 'mock reminder logged';
  try {
    if (!loan.borrower || !loan.borrower.email) throw new Error('borrower has no email');
    console.log(`[LendLoop mock reminder] to=${loan.borrower.email} :: ${loan.borrower.name}, "${loan.toolName}" was due ${loan.endDate} (${loan.daysOverdue} day(s) ago). Please return it.`);
  } catch (error) {
    status = 'failed';
    detail = String(error.message).slice(0, 200);
  }

  // The idempotency key is (loanId, date): replays never create a second record.
  const body = JSON.stringify({ loanId: loan.loanId, date: loan.date, status, detail });
  const ts = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', $env.LENDLOOP_SHARED_SECRET).update(`${ts}.POST.${path}.${body}`).digest('hex');
  out.push({ json: { url: base + path, ts, signature, body } });
}
return out;
